import{_ as o,o as i,c as a,a2 as t}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0021 — Sicurezza e privacy: endpoint GDPR, anonimizzazione, gate di CI (M7-WP2)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0021-security-privacy-details.md","filePath":"adr/0021-security-privacy-details.md"}'),n={name:"adr/0021-security-privacy-details.md"};function r(c,e,d,l,s,u){return i(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0021-—-sicurezza-e-privacy-endpoint-gdpr-anonimizzazione-gate-di-ci-m7-wp2" tabindex="-1">ADR-0021 — Sicurezza e privacy: endpoint GDPR, anonimizzazione, gate di CI (M7-WP2) <a class="header-anchor" href="#adr-0021-—-sicurezza-e-privacy-endpoint-gdpr-anonimizzazione-gate-di-ci-m7-wp2" aria-label="Permalink to &quot;ADR-0021 — Sicurezza e privacy: endpoint GDPR, anonimizzazione, gate di CI (M7-WP2)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.6.5, §2.8.2, §3.2.2, §3.5.1, §3.7, §4.3 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-27</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§3.5 (API), §3.8 (E2EE), §2.6.2 (retention), D-02, D-03, D-05</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì, in modo additivo: <code>GET /me/export</code>, <code>DELETE /me</code>, migrazione <code>0006</code>, impostazione <code>privacy.account_purge_days</code>, job purge</td></tr></tbody></table><p><strong>Aggiornamento 2026-11-02.</strong> Il gate di CI della decisione 6 (<code>security.yml</code>) è stato rimosso e sostituito dalle verifiche locali con <code>task ci</code> (ADR-0036); la regola sui grant concessi da un utente cancellato è modificata da ADR-0041, punto 5 (i grant concessi come <em>manager</em> su vault altrui sono riattribuiti al proprietario del vault). Endpoint GDPR, migrazione <code>0006</code>, <code>privacy.account_purge_days</code> e job di purge restano come qui.</p><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>La 1.0 deve rispondere ai diritti di accesso/portabilità (GDPR art. 15 e 20) e di cancellazione (art. 17), che lo spec §3.5 non prevede, e deve poter essere sottoposta ad audit e penetration test esterni. L&#39;amministratore può già eliminare un utente (ADR-0012), ma l&#39;utente stesso non può, e i dati personali restavano nelle righe di <code>users</code> e <code>audit_log</code>.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><strong><code>GET /me/export</code></strong> (bearer): un file JSON (<code>Content-Disposition: attachment</code>) con profilo, <strong>tutti</strong> i dispositivi (anche revocati), gruppi, vault posseduti (solo metadati e tipi di envelope), share create o su vault propri con i relativi grant, grant ricevuti e voci di audit di cui l&#39;utente è attore o bersaglio. <strong>Non contiene contenuto dei vault</strong>: i privati sono cifrati e il server non può leggerli (lo scrive il campo <code>notice</code>); i condivisi si esportano con l&#39;export ZIP esistente. L&#39;export è registrato in audit (<code>account.export</code>).</li><li><strong><code>DELETE /me</code></strong> con corpo <code>{confirm, acknowledge_data_loss?}</code>: <code>confirm</code> deve essere uguale allo username; se l&#39;utente possiede vault privati, <code>acknowledge_data_loss</code> deve essere <code>true</code> (altrimenti <code>400</code> con l&#39;avviso di irrecuperabilità). L&#39;ultimo amministratore attivo riceve <code>409 INVALID_STATE</code> (con blocco delle righe admin contro le cancellazioni concorrenti). A differenza di <code>DELETE /admin/users/{id}</code>, un amministratore <strong>può</strong> cancellare il proprio account se ne esiste un altro.</li><li><strong>Anonimizzazione, non cancellazione della riga.</strong> <code>users</code> diventa un tombstone: username <code>deleted-&lt;id8&gt;</code>, email <code>deleted-&lt;id&gt;@deleted.invalid</code>, nome <code>NULL</code>, stato <code>deleted</code>, <code>deleted_at</code>; id, ruolo e date restano perché <code>audit_log.actor_id</code>, <code>file_revisions.author_id</code> (in vault di altri) e <code>share_grants.granted_by</code> sono chiavi esterne e la traccia deve restare integra. In <code>audit_log</code> si azzerano <code>ip</code> e <code>details.username</code> per le righe dell&#39;utente; <code>action</code>, <code>target_*</code> e gli id non cambiano. I dispositivi sono cancellati (o, se referenziati da revisioni, revocati e resi anonimi); appartenenze, grant ricevuti e concessi, upload in corso sono cancellati (i grant concessi come <em>manager</em> su vault di altri proprietari sono invece riattribuiti al proprietario del vault, e l&#39;eliminazione dalla console segue lo stesso percorso: ADR-0041); gli export pronti scadono subito. <code>UpsertUserFromToken</code> non riscrive più username, email e nome su una riga <code>deleted</code>: il login risponde <code>USER_SUSPENDED</code>.</li><li><strong>Keycloak</strong>: <code>keycloak.Admin.SetEnabled(false)</code> (con fine delle sessioni), tollerando <code>Disabled</code> e <code>ErrNotFound</code>. L&#39;eliminazione definitiva dell&#39;account nel realm resta a carico del gestore (<code>Admin</code> non espone <code>DeleteUser</code>): lacuna dichiarata in <code>docs/security/data-retention.md</code>.</li><li><strong>Purge</strong>: i vault dell&#39;utente sono eliminati (soft) all&#39;istante. <code>jobs.PurgeDeletedAccounts</code> (nella manutenzione giornaliera) dopo <code>privacy.account_purge_days</code> (predefinito 30, migrazione <code>0006</code>) rimuove ogni vault ancora posseduto (righe, file, revisioni, envelope, riferimenti ai blob e quota), ripete l&#39;anonimizzazione (copre gli account cancellati da un admin, che restano logici fino ad allora), sostituisce <code>keycloak_sub</code> con <code>purged:&lt;id&gt;</code> e valorizza <code>purged_at</code>. I blob liberati sono raccolti dal GC esistente. L&#39;operazione è idempotente.</li><li><strong>Gate di CI</strong> (<code>.github/workflows/security.yml</code>, nuovo file; <code>ci.yml</code> invariato): <code>govulncheck</code> sui tre moduli (bloccante, toolchain <code>1.26.x</code> più recente); <code>yarn npm audit --all --recursive</code> con gate <strong>high</strong> bloccante e report completo non bloccante (moderate/low e deprecazioni sono triagiati ogni settimana); SBOM con syft (SPDX del binario cloud, CycloneDX del repository) e riepilogo licenze come artefatti, con avviso su copyleft forte; gitleaks facoltativo (non bloccante); build reale della Web UI e verifica di CSP, SRI e header (test Go, <code>web/e2e-security</code> in Chromium); rigenerazione dei vettori crittografici con <code>git diff --exit-code</code>; controllo che l&#39;inventario degli endpoint di <code>pentest-scope.md</code> sia allineato a <code>api/openapi.yaml</code> (<code>scripts/pentest-inventory.mjs --check</code>). Esecuzione a ogni PR, su <code>main</code> e ogni lunedì.</li></ol><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Cancellare la riga <code>users</code>.</strong> Scartata: richiederebbe di annullare o riscrivere ovunque le chiavi esterne (audit, revisioni, grant) e di perdere la traccia delle azioni amministrative.</li><li><strong>Export ZIP con i contenuti.</strong> Scartata per i vault privati (il server non può decifrare) e ridondante per i condivisi (export ZIP già disponibile).</li><li><strong>Cancellazione solo differita (retention prima, anonimizzazione poi).</strong> Scartata: lascerebbe dati personali per 30 giorni dopo una richiesta di cancellazione; la retention vale per il contenuto dei vault, non per l&#39;identità.</li><li><strong><code>DELETE /me</code> senza avviso esplicito per i vault privati.</strong> Scartata: la perdita è irreversibile (D-02).</li><li><strong>Gate <code>moderate</code> su <code>yarn npm audit</code>.</strong> Scartata per ora: rimane una deprecazione senza correzione a monte (<code>sliced</code>, via Excalidraw) e avvisi moderati ricorrenti nell&#39;albero transitivo; si rivaluta dopo il primo ciclo settimanale.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Spec da aggiornare: §3.5 con i due endpoint, §2.6.2 con <code>privacy.account_purge_days</code>, la politica di anonimizzazione e la differenza con <code>DELETE /admin/users/{id}</code>.</li><li>Debito: nessuna retention automatica dell&#39;<code>audit_log</code>; nessuna cancellazione dell&#39;account Keycloak; backup non riscritti. Tutti elencati in <code>docs/security/data-retention.md</code>.</li><li>Il <code>package.json</code> radice ora dichiara <code>resolutions</code> (nanoid, lodash-es, katex) per correggere avvisi <em>high</em> transitivi di Excalidraw/chevrotain; vanno riviste a ogni aggiornamento di Excalidraw.</li><li><code>tools/go.mod</code> (toolchain di <code>ci.yml</code>) è a go1.26.7, che ha 13 vulnerabilità della libreria standard raggiunte dal codice (correzioni in 1.26.9/1.26.10): va aggiornato, altrimenti il passo <code>govulncheck</code> di <code>ci.yml</code> resta rosso.</li></ul>',11)])])}const m=o(n,[["render",r]]);export{g as __pageData,m as default};
